class BookingEngine:
    def __init__(self, capacity):
        self.capacity=capacity
        self.rows={}
        self.requests={}
    def reserve(self, request, slot):
        if request in self.requests:
            return self.requests[request]
        if sum(x['slot']==slot for x in self.rows.values()) >= self.capacity:
            return None
        row={'id':request,'slot':slot}
        self.rows[request]=row
        self.requests[request]=row
        return row
    def cancel(self, ident):
        self.rows.pop(ident,None)
    def list(self):
        return list(self.rows.values())
class Catalog:
    def __init__(self, items):
        self.items=items
    def list(self):
        return self.items
    def search(self, keyword):
        return [x for x in self.items if keyword in x['name']]

