const rows=[]; const requests={};
function reserve(request,slot,capacity=2){if(requests[request])return requests[request];if(rows.filter(x=>x.slot===slot).length>=capacity)return null;const row={id:request,slot}; rows.push(row);requests[request]=row;return row;}
function cancel(id){const i=rows.findIndex(x=>x.id===id);if(i>=0)rows.splice(i,1);}
function render(){document.getElementById('rows').textContent=JSON.stringify(rows);}
document.getElementById('book').onclick=()=>{reserve(crypto.randomUUID(),document.getElementById('slot').value);render();};
document.getElementById('cancel').onclick=()=>{cancel(document.getElementById('id').value);render();};

